332	// Find lookup a handler registered for method and path. It also parses URL for path
333	// parameters and load them into context.
334	//
335	// For performance:
336	//
337	// - Get context from `Echo#AcquireContext()`
338	// - Reset it `Context#Reset()`
339	// - Return it `Echo#ReleaseContext()`.
340	func (r *Router) Find(method, path string, c Context) {
341		ctx := c.(*context)
342		ctx.path = path
343		currentNode := r.tree // Current node as root
344	
345		var (
346			// search stores the remaining path to check for match. By each iteration we move from start of path to end of the path
347			// and search value gets shorter and shorter.
348			search      = path
349			searchIndex = 0
350			paramIndex  int           // Param counter
351			paramValues = ctx.pvalues // Use the internal slice so the interface can keep the illusion of a dynamic slice
352		)
