package echo

import (
	"fmt"
	"net/http"
	"runtime/debug"
	"sort"
	"strings"
	"testing"
	"time"
)

var zzRouteList = []string{
	"/", "/a", "/a/b", "/a/:id", "/a/*", "/:id", "/:id/b", "/:id/*", "/a/:id/c", "/*", "/a/b/*", "/a/*/c", "/:a/:b", "/:a/*",
}

var zzPathList = []string{
	"", "/", "//", "///", "/a", "/a/", "/a/b", "/a/b/", "/a/b/c", "/a/b/c/d",
	"/x", "/x/y", "/x/y/z", "/a/x", "/a/x/y", "/a/b/x", "/:id", "/a/:id", "/a/*", "/*",
	"/a//b", "/a/b//c", "/a/b/c/d/e", "/a/b/c/d/e/f",
}

// zzMatches is an independent, conservative implementation of echo's documented
// route matching semantics: static segments must match exactly, ":param" matches
// a single non-empty segment, "*" matches the remainder (possibly empty) but the
// preceding '/' must be present in the path.
func zzMatches(pattern, path string) bool {
	pi, si := 0, 0
	for pi < len(pattern) {
		switch pattern[pi] {
		case '*':
			return true
		case ':':
			for pi < len(pattern) && pattern[pi] != '/' {
				pi++
			}
			if si >= len(path) || path[si] == '/' {
				return false
			}
			for si < len(path) && path[si] != '/' {
				si++
			}
		default:
			if si >= len(path) || path[si] != pattern[pi] {
				return false
			}
			pi++
			si++
		}
	}
	return si == len(path)
}

type zzFindResult struct {
	panicked bool
	panicVal interface{}
	stack    string
	hung     bool
	handler  HandlerFunc
	path     string
	pnames   []string
	pvalues  []string
}

func zzRunFind(e *Echo, path string) (res zzFindResult) {
	c := e.NewContext(nil, nil).(*context)
	done := make(chan zzFindResult, 1)
	go func() {
		defer func() {
			if p := recover(); p != nil {
				done <- zzFindResult{panicked: true, panicVal: p, stack: string(debug.Stack())}
			}
		}()
		e.router.Find(http.MethodGet, path, c)
		done <- zzFindResult{handler: c.handler, path: c.path, pnames: c.pnames, pvalues: append([]string{}, c.pvalues...)}
	}()
	select {
	case r := <-done:
		return r
	case <-time.After(2 * time.Second):
		return zzFindResult{hung: true}
	}
}

type zzFail struct {
	routes []string
	path   string
	kind   string
	detail string
}

func zzKey(f zzFail) string {
	return f.kind + "|" + strings.Join(f.routes, ",") + "|" + f.path
}

func zzSubsets(n, k int) [][]int {
	var res [][]int
	var rec func(start int, cur []int)
	rec = func(start int, cur []int) {
		if len(cur) == k {
			cp := append([]int{}, cur...)
			res = append(res, cp)
			return
		}
		for i := start; i < n; i++ {
			rec(i+1, append(cur, i))
		}
	}
	rec(0, nil)
	return res
}

func TestZZFuzzRouter(t *testing.T) {
	seen := map[string]bool{}
	var fails []zzFail

	for size := 1; size <= 4; size++ {
		for _, idxs := range zzSubsets(len(zzRouteList), size) {
			routes := make([]string, 0, size)
			for _, i := range idxs {
				routes = append(routes, zzRouteList[i])
			}
			e := New()
			for _, rp := range routes {
				rp := rp
				e.router.Add(http.MethodGet, rp, func(c Context) error { return nil })
			}
			for _, path := range zzPathList {
				res := zzRunFind(e, path)
				var f *zzFail
				switch {
				case res.hung:
					f = &zzFail{routes, path, "HANG", "Find did not return within 2s"}
				case res.panicked:
					f = &zzFail{routes, path, "PANIC", fmt.Sprintf("%v\n%s", res.panicVal, res.stack)}
				default:
					matched := res.handler != NotFoundHandler
					// Which routes match per independent matcher?
					var matching []string
					for _, rp := range routes {
						if zzMatches(rp, path) {
							matching = append(matching, rp)
						}
					}
					if matched {
						if !zzMatches(res.path, path) {
							f = &zzFail{routes, path, "WRONG-HANDLER",
								fmt.Sprintf("router matched route %q which does not match request path %q (matching routes: %v)", res.path, path, matching)}
						} else if len(matching) == 0 {
							f = &zzFail{routes, path, "WRONG-HANDLER",
								fmt.Sprintf("router matched route %q but independent matcher says no route matches", res.path)}
						}
					} else {
						if len(matching) > 0 {
							f = &zzFail{routes, path, "MISSED-MATCH",
								fmt.Sprintf("router returned NotFound but routes %v match the path", matching)}
						}
					}
				}
				if f != nil {
					k := zzKey(*f)
					if !seen[k] {
						seen[k] = true
						fails = append(fails, *f)
					}
				}
			}
		}
	}

	// report: sort by number of routes then kind
	sort.SliceStable(fails, func(i, j int) bool {
		if len(fails[i].routes) != len(fails[j].routes) {
			return len(fails[i].routes) < len(fails[j].routes)
		}
		return fails[i].kind < fails[j].kind
	})
	for i, f := range fails {
		if i > 40 {
			t.Logf("... %d more failures", len(fails)-i)
			break
		}
		detail := f.detail
		if len(detail) > 1200 {
			detail = detail[:1200]
		}
		t.Logf("FAIL[%d] kind=%s routes=%v path=%q\n  %s", i, f.kind, f.routes, f.path, detail)
	}
	t.Logf("total unique failures: %d", len(fails))
}
