package echo

import (
	"fmt"
	"io/ioutil"
	"math/rand"
	"net/http"
	"sort"
	"strings"
	"testing"
)

var zzSegs = []string{"a", "b", "c", "x", "ab", ":id", ":a", ":b", "*", "aa", "abc", ":id2"}

func zzRandRoute(rnd *rand.Rand) string {
	n := 1 + rnd.Intn(4)
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, zzSegs[rnd.Intn(len(zzSegs))])
	}
	p := "/" + strings.Join(parts, "/")
	if rnd.Intn(4) == 0 {
		p += "/"
	}
	return p
}

func zzRandPath(rnd *rand.Rand) string {
	n := rnd.Intn(5)
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, zzSegs[rnd.Intn(len(zzSegs))])
	}
	p := "/" + strings.Join(parts, "/")
	switch rnd.Intn(6) {
	case 0:
		p = p + "/"
	case 1:
		p = p + "//"
	case 2:
		p = "/" + p
	}
	return p
}

func TestZZFuzzRouterRandom(t *testing.T) {
	rnd := rand.New(rand.NewSource(42))
	seen := map[string]bool{}
	var fails []zzFail
	iters := 60000
	for it := 0; it < iters; it++ {
		nRoutes := 1 + rnd.Intn(6)
		routes := make([]string, 0, nRoutes)
		for i := 0; i < nRoutes; i++ {
			routes = append(routes, zzRandRoute(rnd))
		}
		e := New()
		for _, rp := range routes {
			e.router.Add(http.MethodGet, rp, func(c Context) error { return nil })
		}
		nPaths := 1 + rnd.Intn(6)
		for i := 0; i < nPaths; i++ {
			path := zzRandPath(rnd)
			res := zzRunFind(e, path)
			var f *zzFail
			switch {
			case res.hung:
				f = &zzFail{routes, path, "HANG", "Find did not return within 2s"}
			case res.panicked:
				f = &zzFail{routes, path, "PANIC", fmt.Sprintf("%v\n%s", res.panicVal, res.stack)}
			default:
				matched := res.handler != nil && fmt.Sprintf("%p", res.handler) != fmt.Sprintf("%p", HandlerFunc(NotFoundHandler))
				var matching []string
				for _, rp := range routes {
					if zzMatches(rp, path) {
						matching = append(matching, rp)
					}
				}
				if matched {
					if !zzMatches(res.path, path) {
						f = &zzFail{routes, path, "WRONG-HANDLER",
							fmt.Sprintf("router matched route %q which does not match request path %q (matching: %v)", res.path, path, matching)}
					}
				} else if len(matching) > 0 {
					f = &zzFail{routes, path, "MISSED-MATCH",
						fmt.Sprintf("router returned NotFound but routes %v match the path", matching)}
				}
			}
			if f != nil {
				k := zzKey(*f)
				if !seen[k] {
					seen[k] = true
					fails = append(fails, *f)
				}
			}
		}
	}
	byKind := map[string]int{}
	for _, f := range fails {
		byKind[f.kind]++
	}
	t.Logf("iterations=%d counts by kind: %v", iters, byKind)
	sort.SliceStable(fails, func(i, j int) bool {
		if len(fails[i].routes) != len(fails[j].routes) {
			return len(fails[i].routes) < len(fails[j].routes)
		}
		return fails[i].kind < fails[j].kind
	})
	var sb strings.Builder
	for i, f := range fails {
		fmt.Fprintf(&sb, "FAIL[%d] kind=%s routes=%v path=%q\n  %s\n", i, f.kind, f.routes, f.path, f.detail)
	}
	_ = ioutil.WriteFile("/tmp/zz_fails2.txt", []byte(sb.String()), 0644)
	shown := 0
	for _, f := range fails {
		if f.kind == "PANIC" || f.kind == "HANG" {
			d := f.detail
			if len(d) > 1500 {
				d = d[:1500]
			}
			t.Logf("PANIC/HANG kind=%s routes=%v path=%q\n  %s", f.kind, f.routes, f.path, d)
			shown++
			if shown > 10 {
				break
			}
		}
	}
	t.Logf("total unique failures: %d (full list /tmp/zz_fails2.txt)", len(fails))
}
EOF
