		{"X-Url-Scheme", &context{request: &http.Request{Header: http.Header{HeaderXUrlScheme: []string{"https"}}}}, "https"},
		{"none", &context{request: &http.Request{}}, "http"},
		{"ignores invalid X-Forwarded-Proto and uses X-Forwarded-Protocol", &context{request: &http.Request{Header: http.Header{
