func match(node *refNode, path string, pos int) (string, bool) {
    if pos == len(path) {
        if node.terminal { return node.pattern, true }
        // fall through to any child? An any child matches empty remainder
        if node.anyChild != nil && node.anyChild.terminal { return node.anyChild.pattern, true }
        return "", false
    }
    // try static
    if c := node.staticChildren[path[pos]]; c != nil {
        if p, ok := match(c, path, pos+1); ok { return p, true }
    }
    // try param: consume until '/' (non-empty)
    if node.paramChild != nil {
        i := pos
        for i < len(path) && path[i] != '/' { i++ }
        if i > pos { // non-empty
            if p, ok := match(node.paramChild, path, i); ok { return p, true }
        }
    }
    // try any: consumes the rest
    if node.anyChild != nil && node.anyChild.terminal {
        return node.anyChild.pattern, true
    }
    return "", false
