package echo

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"sort"
	"strings"
	"testing"
)

// ---- reference implementation of echo's documented routing semantics ----
// static segments must match exactly, ":param" matches one non-empty segment,
// "*" matches the remainder (possibly empty, but the preceding '/' must be present).
// Priority: static > param > any, with backtracking (DFS).

type zzRefNode struct {
	staticChildren map[byte]*zzRefNode
	paramChild     *zzRefNode
	anyChild       *zzRefNode
	pattern        string // "" if no route registered at this node
}

func zzRefInsert(root *zzRefNode, pattern string) {
	n := root
	i := 0
	for i < len(pattern) {
		c := pattern[i]
		switch {
		case c == ':':
			for i < len(pattern) && pattern[i] != '/' {
				i++
			}
			if n.paramChild == nil {
				n.paramChild = &zzRefNode{}
			}
			n = n.paramChild
		case c == '*':
			if n.anyChild == nil {
				n.anyChild = &zzRefNode{}
			}
			n = n.anyChild
			n.pattern = pattern // last registration wins
			return              // everything after '*' is unreachable in echo's Find
		default:
			if n.staticChildren == nil {
				n.staticChildren = map[byte]*zzRefNode{}
			}
			if n.staticChildren[c] == nil {
				n.staticChildren[c] = &zzRefNode{}
			}
			n = n.staticChildren[c]
			i++
		}
	}
	n.pattern = pattern
}

func zzRefMatch(n *zzRefNode, path string, pos int) (string, bool) {
	if pos == len(path) {
		if n.pattern != "" {
			return n.pattern, true
		}
		if n.anyChild != nil && n.anyChild.pattern != "" {
			return n.anyChild.pattern, true
		}
		return "", false
	}
	if c := n.staticChildren[path[pos]]; c != nil {
		if p, ok := zzRefMatch(c, path, pos+1); ok {
			return p, true
		}
	}
	if n.paramChild != nil {
		i := pos
		for i < len(path) && path[i] != '/' {
			i++
		}
		if i > pos { // non-empty param
			if p, ok := zzRefMatch(n.paramChild, path, i); ok {
				return p, true
			}
		}
	}
	if n.anyChild != nil && n.anyChild.pattern != "" {
		return n.anyChild.pattern, true
	}
	return "", false
}

func zzRefFind(routes []string, path string) (string, bool) {
	root := &zzRefNode{}
	for _, r := range routes {
		zzRefInsert(root, r)
	}
	return zzRefMatch(root, path, 0)
}

var zzRouteList3 = []string{
	"/", "/a", "/a/b", "/a/:id", "/a/*", "/:id", "/:id/b", "/:id/*", "/a/:id/c", "/*",
	"/a/b/*", "/a/*/c", "/:a/:b", "/:a/*", "/*/c", "/a/*/b", "/:id/b/c", "/a/:id/*", "/:id/:id2",
}

var zzPathList3 = []string{
	"", "/", "//", "///", "/a", "/a/", "/a/b", "/a/b/", "/a/b/c", "/a/b/c/d",
	"/x", "/x/y", "/x/y/z", "/a/x", "/a/x/y", "/a/b/x", "/:id", "/a/:id", "/a/*", "/*",
	"/a//b", "/a/b//c", "/a/b/c/d/e", "/a/b/c/d/e/f", "/a/b/c/d/e/f/g",
}

type zzCase struct {
	routes []string
	path   string
	got    string // "" means NotFound
	exp    string // "" means expected NotFound
}

func TestZZRefCompare(t *testing.T) {
	var mismatches []zzCase
	for size := 1; size <= 4; size++ {
		for _, idxs := range zzSubsets(len(zzRouteList3), size) {
			routes := make([]string, 0, size)
			for _, i := range idxs {
				routes = append(routes, zzRouteList3[i])
			}
			e := New()
			for _, rp := range routes {
				e.router.Add(http.MethodGet, rp, func(c Context) error { return nil })
			}
			for _, path := range zzPathList3 {
				res := zzRunFind(e, path)
				if res.hung || res.panicked {
					t.Errorf("PANIC/HANG routes=%v path=%q panic=%v hung=%v", routes, path, res.panicVal, res.hung)
					continue
				}
				got := ""
				if res.handler != nil && fmt.Sprintf("%p", res.handler) != fmt.Sprintf("%p", HandlerFunc(NotFoundHandler)) {
					got = res.path
				}
				exp, ok := zzRefFind(routes, path)
				if !ok {
					exp = ""
				}
				if got != exp {
					mismatches = append(mismatches, zzCase{routes, path, got, exp})
				}
			}
		}
	}
	// classify
	byKind := map[string]int{}
	for _, m := range mismatches {
		k := "other"
		if strings.Contains(m.path, "//") || m.path == "" {
			k = "path-with-empty-segment"
		}
		byKind[k]++
	}
	t.Logf("mismatches: %d %v", len(mismatches), byKind)
	sort.SliceStable(mismatches, func(i, j int) bool { return len(mismatches[i].routes) < len(mismatches[j].routes) })
	var sb strings.Builder
	for i, m := range mismatches {
		fmt.Fprintf(&sb, "[%d] routes=%v path=%q router=%q ref=%q\n", i, m.routes, m.path, m.got, m.exp)
	}
	_ = ioutil.WriteFile("/tmp/zz_mismatch.txt", []byte(sb.String()), 0644)
	shown := 0
	for _, m := range mismatches {
		if !strings.Contains(m.path, "//") && m.path != "" {
			t.Logf("OTHER-MISMATCH routes=%v path=%q router=%q ref=%q", m.routes, m.path, m.got, m.exp)
			shown++
			if shown > 20 {
				break
			}
		}
	}
	t.Logf("non-empty-segment mismatches shown: %d", shown)
}
EOF
