package echo

import (
	"fmt"
	"io/ioutil"
	"math/rand"
	"net/http"
	"strings"
	"testing"
)

// zzRefParamValues extracts param values for a pattern that matches path (segment walk).
func zzRefParamValues(pattern, path string) ([]string, bool) {
	var vals []string
	pi, si := 0, 0
	for pi < len(pattern) {
		switch pattern[pi] {
		case '*':
			vals = append(vals, path[si:])
			return vals, true
		case ':':
			for pi < len(pattern) && pattern[pi] != '/' {
				pi++
			}
			if si >= len(path) || path[si] == '/' {
				return nil, false
			}
			j := si
			for j < len(path) && path[j] != '/' {
				j++
			}
			vals = append(vals, path[si:j])
			si = j
		default:
			if si >= len(path) || path[si] != pattern[pi] {
				return nil, false
			}
			pi++
			si++
		}
	}
	if si != len(path) {
		return nil, false
	}
	return vals, true
}

var zzSegs4 = []string{"a", "b", "c", "x", "ab", ":id", ":a", ":b", "*", "aa", "abc", ":id2", "a:b", "a*b", ":", "*x"}

func zzRandRoute4(rnd *rand.Rand) string {
	n := 1 + rnd.Intn(5)
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, zzSegs4[rnd.Intn(len(zzSegs4))])
	}
	p := "/" + strings.Join(parts, "/")
	switch rnd.Intn(8) {
	case 0:
		p += "/"
	case 1:
		p = "/" + p
	}
	return p
}

func zzRandPath4(rnd *rand.Rand) string {
	n := rnd.Intn(6)
	parts := make([]string, 0, n)
	for i := 0; i < n; i++ {
		parts = append(parts, zzSegs4[rnd.Intn(len(zzSegs4))])
	}
	p := "/" + strings.Join(parts, "/")
	switch rnd.Intn(8) {
	case 0:
		p = p + "/"
	case 1:
		p = p + "//"
	case 2:
		p = "/" + p
	}
	return p
}

func TestZZFuzzRouterRandom4(t *testing.T) {
	rnd := rand.New(rand.NewSource(1234))
	seen := map[string]bool{}
	var fails []zzFail
	iters := 200000
	for it := 0; it < iters; it++ {
		nRoutes := 1 + rnd.Intn(8)
		routes := make([]string, 0, nRoutes)
		for i := 0; i < nRoutes; i++ {
			routes = append(routes, zzRandRoute4(rnd))
		}
		e := New()
		for _, rp := range routes {
			e.router.Add(http.MethodGet, rp, func(c Context) error { return nil })
		}
		nPaths := 1 + rnd.Intn(6)
		for i := 0; i < nPaths; i++ {
			path := zzRandPath4(rnd)
			res := zzRunFind(e, path)
			var f *zzFail
			switch {
			case res.hung:
				f = &zzFail{routes, path, "HANG", "Find did not return within 2s"}
			case res.panicked:
				f = &zzFail{routes, path, "PANIC", fmt.Sprintf("%v\n%s", res.panicVal, res.stack)}
			default:
				matched := res.handler != nil && fmt.Sprintf("%p", res.handler) != fmt.Sprintf("%p", HandlerFunc(NotFoundHandler))
				if matched {
					// param values check against the matched pattern
					refVals, ok := zzRefParamValues(res.path, path)
					if !ok {
						f = &zzFail{routes, path, "WRONG-HANDLER",
							fmt.Sprintf("router matched route %q which does not match request path (params %v)", res.path, res.pnames)}
					} else if len(refVals) != len(res.pnames) {
						f = &zzFail{routes, path, "PARAM-COUNT",
							fmt.Sprintf("route %q matched: pnames=%v pvalues=%v, expected %d values %v", res.path, res.pnames, res.pvalues, len(refVals), refVals)}
					} else {
						for k := range refVals {
							if res.pvalues[k] != refVals[k] {
								f = &zzFail{routes, path, "PARAM-VALUE",
									fmt.Sprintf("route %q matched: pnames=%v pvalues=%v, expected %v", res.path, res.pnames, res.pvalues, refVals)}
								break
							}
						}
					}
				}
			}
			if f != nil {
				k := zzKey(*f)
				if !seen[k] {
					seen[k] = true
					fails = append(fails, *f)
				}
			}
		}
	}
	byKind := map[string]int{}
	for _, f := range fails {
		byKind[f.kind]++
	}
	t.Logf("iterations=%d counts by kind: %v", iters, byKind)
	var sb strings.Builder
	for i, f := range fails {
		fmt.Fprintf(&sb, "FAIL[%d] kind=%s routes=%v path=%q\n  %s\n", i, f.kind, f.routes, f.path, f.detail)
	}
	_ = ioutil.WriteFile("/tmp/zz_fails4.txt", []byte(sb.String()), 0644)
	shown := 0
	for _, f := range fails {
		if f.kind == "PANIC" || f.kind == "HANG" || f.kind == "PARAM-VALUE" || f.kind == "PARAM-COUNT" {
			d := f.detail
			if len(d) > 1200 {
				d = d[:1200]
			}
			t.Logf("%s routes=%v path=%q\n  %s", f.kind, f.routes, f.path, d)
			shown++
			if shown > 15 {
				break
			}
		}
	}
	t.Logf("total unique failures: %d (full list /tmp/zz_fails4.txt)", len(fails))
}
